		} else {
			$criteria = new Criteria(Tbrh014ConceptoPeer::DATABASE_NAME);
			$criteria->add(Tbrh014ConceptoPeer::CO_CONCEPTO, $pks, Criteria::IN);
			$objs = Tbrh014ConceptoPeer::doSelect($criteria, $con);
